:root {
  /* Colors */
  --color-paper-canvas: #ffffff;
  --color-linen-card: #fefdfb;
  --color-stone-shelf: #f4f3f0;
  --color-jet-ink: #000000;
  --color-charcoal-ink: #1b1a18;
  --color-pewter-caption: #55534e;
  --color-ash-hint: #7b7974;
  --color-pebble-border: #d1cdc7;
  --color-keylime-action: #cbd810;
  --color-cobalt-signal: #395afa;
  --color-ember-rust: #b53d0a;
  --color-moss-olive: #808000;
  --color-orchid-signal: #cc089e;

  /* Typography — Font Families */
  --font-roobert-vf: "Roobert", "General Sans", "Inter Display", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Typography — Scale */
  --text-small: 9.6px;
  --leading-small: 1.15;
  --tracking-small: 0px;
  --text-caption: 12px;
  --leading-caption: 1.1;
  --tracking-caption: 1.44px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.3;
  --tracking-body-sm: 0px;
  --text-body: 16px;
  --leading-body: 1.5;
  --tracking-body: 0px;
  --text-body-lg: 20px;
  --leading-body-lg: 1.3;
  --tracking-body-lg: 0px;
  --text-subheading: 23.2px;
  --leading-subheading: 1.3;
  --tracking-subheading: 0px;
  --text-heading-sm: 44px;
  --leading-heading-sm: 1.1;
  --tracking-heading-sm: -0.88px;
  --text-heading: 48px;
  --leading-heading: 1;
  --tracking-heading: -1.92px;
  --text-heading-lg: 72px;
  --leading-heading-lg: 1;
  --tracking-heading-lg: -2.16px;
  --text-display: 88px;
  --leading-display: 1;
  --tracking-display: -3.52px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-medium-2: 575;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-14: 14px;
  --spacing-16: 16px;
  --spacing-18: 18px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-48: 48px;
  --spacing-64: 64px;
  --spacing-80: 80px;

  /* Layout */
  --layout-max-width: 1280px;
  --layout-section-gap: 80px;
  --layout-card-padding: 20px;
  --layout-element-gap: 16px;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-sm-2: 6px;
  --radius-md: 8px;
  --radius-md-2: 10px;
  --radius-lg: 12px;
  --radius-lg-2: 14px;
  --radius-lg-3: 16px;
  --radius-xl: 18px;
  --radius-xl-2: 20px;
  --radius-2xl: 24px;
  --radius-2xl-2: 32px;
  --radius-3xl: 48px;
  --radius-full: 1600px;

  /* Named Radii */
  --radius-cards: 18px;
  --radius-smallCards: 14px;
  --radius-buttons: 12px;
  --radius-pills: 1600px;
  --radius-tags: 1600px;
  --radius-badges: 1600px;
  --radius-inputs: 20px;
  --radius-avatars: 16px;
  --radius-images: 24px;
  --radius-innerTiles: 10px;
  --radius-smallElements: 6px;
  --radius-nav: 24px;
  --radius-sections: 48px;

  /* Shadows */
  --shadow-subtle: rgba(255, 255, 255, 0.05) 0px 0px 0px 1px inset;
  --shadow-sm: rgb(244, 243, 240) 0px 0px 0px 2px inset;
  --shadow-sm-2: rgb(240, 248, 255) 0px 0px 0px 2px inset;
  --shadow-md: rgba(0, 0, 0, 0.15) 0px 4px 8px 0px;
  --shadow-lg: rgba(21, 21, 24, 0.1) 0px 12px 36px -8px;

  /* Surfaces */
  --surface-paper-canvas: #ffffff;
  --surface-stone-shelf: #f4f3f0;
  --surface-linen-card: #fefdfb;
  --surface-jet-ink: #000000;
}

